-- both missions DRAFT. Exclusion rules are not applied by this file.
-- ============================================

\set ON_ERROR_STOP on
BEGIN;

DO $do$
DECLARE
    v_author   text;
    v_client   text;
    v_mission  text;
    v_campaign text;
    v_list     text;
    v_count    integer;
BEGIN
    SELECT id INTO v_author FROM "User" WHERE role = 'MANAGER' AND "isActive" ORDER BY "createdAt" LIMIT 1;

    -- N2F ------------------------------------------------------
    SELECT id INTO v_client FROM "Client" WHERE lower(name) = lower('N2F') ORDER BY "createdAt" LIMIT 1;
    IF v_client IS NULL THEN
        v_client := 'm2611cli455e46f7a2a59cfeee48';
        IF v_author IS NOT NULL AND to_regclass('"ClientOnboarding"') IS NOT NULL THEN
            VALUES ('m2611onb455e46f7a2a59cfeee48', v_client, 'IN_PROGRESS', '{"website":"https://www.n2f.com/","icp":"DAF, CFO, directeurs administratifs et financiers, responsables financiers (base fournie par N2F)","pitch":"À compléter : pas de script dans le mail de Hichem du 09/11/2026. Référence produit : https://www.n2f.com/"}'::jsonb, '{}'::jsonb, 'Mail « N2F campagnes » de Hichem Hammouche (2026-11-09) : lien https://www.n2f.com/ et la base DAF « N2Fdaf-base-pour-suzalie-conseil.xlsx ».', v_author, now())
            ON CONFLICT DO NOTHING;
        END IF;
        RAISE NOTICE 'N2F: client created';
    ELSE
        RAISE NOTICE 'N2F: existing client %', v_client;
    END IF;

    SELECT id INTO v_mission FROM "Mission" WHERE "clientId" = v_client AND name = 'N2F — Prospection DAF' LIMIT 1;
    IF v_mission IS NULL THEN
        v_mission := 'm2611mis455e46f7a2a59cfeee48';
        VALUES (v_mission, v_client, 'N2F — Prospection DAF', 'Appeler les DAF, CFO et responsables financiers de la base fournie par N2F et décrocher des rendez-vous de présentation de N2F (gestion des notes de frais).', 'CALL', ARRAY['CALL']::"Channel"[], now(), now() + interval '3 months', 'DRAFT', false, now());
        RAISE NOTICE 'N2F: mission created (DRAFT)';
    ELSE
        RAISE NOTICE 'N2F: mission already there';
    END IF;

    SELECT id INTO v_campaign FROM "Campaign" WHERE "missionId" = v_mission AND name = 'N2F — DAF' LIMIT 1;
    IF v_campaign IS NULL THEN
        v_campaign := 'm2611cmp455e46f7a2a59cfeee48';
        VALUES (v_campaign, v_mission, 'N2F — DAF', 'DAF, CFO, directeurs administratifs et financiers, responsables financiers (base fournie par N2F)', 'À compléter : pas de script dans le mail de Hichem du 09/11/2026. Référence produit : https://www.n2f.com/', NULL, true, now());
        RAISE NOTICE 'N2F: campaign created';
    ELSE
        RAISE NOTICE 'N2F: campaign already there';
    END IF;

    SELECT id INTO v_list FROM "List" WHERE "missionId" = v_mission AND name = 'Base DAF N2F' LIMIT 1;
    IF v_list IS NULL THEN
        v_list := 'm2611lst455e46f7a2a59cfeee48';
        VALUES (v_list, v_mission, 'Base DAF N2F', 'CLIENT', 'Fichier client N2F (mail de Hichem Hammouche, 2026-11-09)', '{"importType":"sql","file":"n2f-daf-base.xlsx","receivedAt":"2026-11-09","sentBy":"Hichem Hammouche","rows":401,"duplicateRowsMerged":9}'::jsonb, now());
        -- The list → script link exists only on recent schemas.
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'List' AND column_name = 'campaignId') THEN
            EXECUTE 'UPDATE "List" SET "campaignId" = $1 WHERE id = $2' USING v_campaign, v_list;
        END IF;
    END IF;

    SELECT count(*) INTO v_count FROM "Company" WHERE "listId" = v_list;
    IF v_count > 0 THEN
        RAISE NOTICE 'N2F: list already holds % companies, not re-imported', v_count;
    ELSE
        ON CONFLICT (id) DO NOTHING;

        ON CONFLICT (id) DO NOTHING;

        RAISE NOTICE 'N2F: list filled with 371 companies and 392 contacts';
    END IF;

    -- Denterlab ------------------------------------------------------
    SELECT id INTO v_client FROM "Client" WHERE lower(name) = lower('Denterlab') ORDER BY "createdAt" LIMIT 1;
    IF v_client IS NULL THEN
        v_client := 'm2611clifbbf584430bdec594bd7';
        IF v_author IS NOT NULL AND to_regclass('"ClientOnboarding"') IS NOT NULL THEN
            VALUES ('m2611onbfbbf584430bdec594bd7', v_client, 'IN_PROGRESS', '{"icp":"Chirurgiens-dentistes et cabinets dentaires (praticien décideur, en passant le secrétariat)","pitch":"Laboratoire Denterlab (Paris) : 3 premiers travaux d''essai 100 % gratuits et sans engagement. Matériaux haut de gamme (Ivoclar Vivadent, Zircone suisse Metoxit), garantie 3 ans, triple contrôle. Couronne Full Zircone ou Céramo-Métal 55 €, E-max 80 €, gouttières dès 35 €. Ramassage et livraison gratuits, empreintes physiques ou numériques."}'::jsonb, '{"base":"--- Introduction ---\nPhase 1 : Franchir le barrage de la secrétaire\n\n« Bonjour Madame / Monsieur, [Votre Prénom] du laboratoire Denterlab à Paris. Je contacte le Docteur au sujet de la prise en charge de nos 3 prothèses d''essai offertes pour son cabinet. Est-il disponible 30 secondes ou préférez-vous que je le rappelle entre deux rendez-vous ? »\n\nConseil : l''expression « 3 prothèses d''essai offertes » positionne l''appel sur une opportunité concrète plutôt que sur un démarchage classique.\n\nPhase 2 : Accroche directe avec le Praticien (30 secondes)\n\n« Bonjour Docteur [Nom], [Votre Prénom] du laboratoire Denterlab. Je vais être très direct : je ne vous demande pas de changer vos habitudes du jour au lendemain.\n\nNous accompagnons les cabinets qui veulent réduire leurs coûts prothétiques tout en exigeant une précision irréprochable et zéro retouche.\n\nPour vous prouver notre niveau de finition sur vos cas réels, nous prenons en charge l''intégralité de vos 3 premiers travaux d''essai, 100 % gratuits et sans aucun engagement. »\n\n--- Decouverte ---\nPhase 3 : Arguments clés & Preuves (mots simples)\n\n« Concrètement, travailler avec nous, c''est :\n\n1. La qualité certifiée : matériaux haut de gamme (Ivoclar Vivadent, Zircone suisse Metoxit), garantie 3 ans et triple contrôle avant expédition.\n2. Des tarifs ultra-compétitifs : par exemple, la couronne Full Zircone ou Céramo-Métal est à 55 €, l''E-max à 80 €, et les gouttières dès 35 € / 36 €.\n3. Zéro contrainte logistique : ramassage et livraison gratuits par coursier ou Chronopost. Traitement direct des empreintes physiques ou des flux numériques de caméra intra-orale. »\n\n--- Objections ---\n« J''ai déjà mon laboratoire local et j''en suis très satisfait. »\n→ « C''est une excellente chose Docteur, l''objectif n''est pas de rompre avec votre prothésiste habituel. Gardez-nous simplement comme alternative fiable pour vos hausses de volume ou pour comparer les finitions et vos marges. Le test est totalement gratuit sur 3 cas : vous jugez sur pièce sans dépenser 1 centime. »\n\n« Moins cher, ça veut dire mauvaise qualité / prothèse importée bas de gamme. »\n→ « C''est justement pour lever ce doute que nous offrons 3 cas complets. Nous utilisons les blocs Zircone suisses Metoxit et la céramique Ivoclar d''origine Liechtenstein, le tout garanti 3 ans. Si l''ajustage ou l''occlusion ne vous conviennent pas, vous n''aurez rien perdu. »\n\n« Envoyez-moi un e-mail ou une plaquette. »\n→ « Je vous l''envoie tout de suite par e-mail avec notre grille complète. Quel est le type de prothèse que vous posez le plus en ce moment : du fixe (zircone, E-max) ou de l''amovible ? Je vous surligne directement nos prix dessus et je glisse le bon pour vos 3 cas d''essai. »\n\n--- Closing ---\nPhase 4 : Appel à l''action\n\n« Avez-vous une empreinte physique au cabinet aujourd''hui ou un fichier numérique 3D à nous envoyer d''ici demain pour lancer ce premier cas test gratuit ? »\n\nAlternative si le praticien manque de temps immédiatement :\n« Préférez-vous qu''un coursier passe récupérer votre boîte d''empreinte demain, ou qu''on cale 5 minutes avec notre responsable prothésiste pour caler vos fiches techniques ? »"}'::jsonb, 'Mail « DENTERLAB mission » de Hichem Hammouche (2026-11-09) : script d''appel en 4 phases + objections. Pas encore de liste.', v_author, now())
            ON CONFLICT DO NOTHING;
        END IF;
        RAISE NOTICE 'Denterlab: client created';
    ELSE
        RAISE NOTICE 'Denterlab: existing client %', v_client;
    END IF;

    SELECT id INTO v_mission FROM "Mission" WHERE "clientId" = v_client AND name = 'Denterlab — Cabinets dentaires' LIMIT 1;
    IF v_mission IS NULL THEN
        v_mission := 'm2611misfbbf584430bdec594bd7';
        VALUES (v_mission, v_client, 'Denterlab — Cabinets dentaires', 'Faire tester Denterlab aux chirurgiens-dentistes : obtenir l''envoi d''un premier cas (3 prothèses d''essai offertes, sans engagement) ou un créneau avec le responsable prothésiste.', 'CALL', ARRAY['CALL']::"Channel"[], now(), now() + interval '3 months', 'DRAFT', false, now());
        RAISE NOTICE 'Denterlab: mission created (DRAFT)';
    ELSE
        RAISE NOTICE 'Denterlab: mission already there';
    END IF;

    SELECT id INTO v_campaign FROM "Campaign" WHERE "missionId" = v_mission AND name = 'Denterlab — 3 prothèses d''essai offertes' LIMIT 1;
    IF v_campaign IS NULL THEN
        v_campaign := 'm2611cmpfbbf584430bdec594bd7';
        VALUES (v_campaign, v_mission, 'Denterlab — 3 prothèses d''essai offertes', 'Chirurgiens-dentistes et cabinets dentaires (praticien décideur, en passant le secrétariat)', 'Laboratoire Denterlab (Paris) : 3 premiers travaux d''essai 100 % gratuits et sans engagement. Matériaux haut de gamme (Ivoclar Vivadent, Zircone suisse Metoxit), garantie 3 ans, triple contrôle. Couronne Full Zircone ou Céramo-Métal 55 €, E-max 80 €, gouttières dès 35 €. Ramassage et livraison gratuits, empreintes physiques ou numériques.', '--- Introduction ---
Phase 1 : Franchir le barrage de la secrétaire

« Bonjour Madame / Monsieur, [Votre Prénom] du laboratoire Denterlab à Paris. Je contacte le Docteur au sujet de la prise en charge de nos 3 prothèses d''essai offertes pour son cabinet. Est-il disponible 30 secondes ou préférez-vous que je le rappelle entre deux rendez-vous ? »

Conseil : l''expression « 3 prothèses d''essai offertes » positionne l''appel sur une opportunité concrète plutôt que sur un démarchage classique.

Phase 2 : Accroche directe avec le Praticien (30 secondes)

« Bonjour Docteur [Nom], [Votre Prénom] du laboratoire Denterlab. Je vais être très direct : je ne vous demande pas de changer vos habitudes du jour au lendemain.

Nous accompagnons les cabinets qui veulent réduire leurs coûts prothétiques tout en exigeant une précision irréprochable et zéro retouche.

Pour vous prouver notre niveau de finition sur vos cas réels, nous prenons en charge l''intégralité de vos 3 premiers travaux d''essai, 100 % gratuits et sans aucun engagement. »

--- Decouverte ---
Phase 3 : Arguments clés & Preuves (mots simples)

« Concrètement, travailler avec nous, c''est :

1. La qualité certifiée : matériaux haut de gamme (Ivoclar Vivadent, Zircone suisse Metoxit), garantie 3 ans et triple contrôle avant expédition.
2. Des tarifs ultra-compétitifs : par exemple, la couronne Full Zircone ou Céramo-Métal est à 55 €, l''E-max à 80 €, et les gouttières dès 35 € / 36 €.
3. Zéro contrainte logistique : ramassage et livraison gratuits par coursier ou Chronopost. Traitement direct des empreintes physiques ou des flux numériques de caméra intra-orale. »

--- Objections ---
« J''ai déjà mon laboratoire local et j''en suis très satisfait. »
→ « C''est une excellente chose Docteur, l''objectif n''est pas de rompre avec votre prothésiste habituel. Gardez-nous simplement comme alternative fiable pour vos hausses de volume ou pour comparer les finitions et vos marges. Le test est totalement gratuit sur 3 cas : vous jugez sur pièce sans dépenser 1 centime. »

« Moins cher, ça veut dire mauvaise qualité / prothèse importée bas de gamme. »
→ « C''est justement pour lever ce doute que nous offrons 3 cas complets. Nous utilisons les blocs Zircone suisses Metoxit et la céramique Ivoclar d''origine Liechtenstein, le tout garanti 3 ans. Si l''ajustage ou l''occlusion ne vous conviennent pas, vous n''aurez rien perdu. »

« Envoyez-moi un e-mail ou une plaquette. »
→ « Je vous l''envoie tout de suite par e-mail avec notre grille complète. Quel est le type de prothèse que vous posez le plus en ce moment : du fixe (zircone, E-max) ou de l''amovible ? Je vous surligne directement nos prix dessus et je glisse le bon pour vos 3 cas d''essai. »

--- Closing ---
Phase 4 : Appel à l''action

« Avez-vous une empreinte physique au cabinet aujourd''hui ou un fichier numérique 3D à nous envoyer d''ici demain pour lancer ce premier cas test gratuit ? »

Alternative si le praticien manque de temps immédiatement :
« Préférez-vous qu''un coursier passe récupérer votre boîte d''empreinte demain, ou qu''on cale 5 minutes avec notre responsable prothésiste pour caler vos fiches techniques ? »', true, now());
        RAISE NOTICE 'Denterlab: campaign created';
    ELSE
        RAISE NOTICE 'Denterlab: campaign already there';
    END IF;

END
$do$;

COMMIT;

-- Check
SELECT c.name AS client, m.name AS mission, m.status,
       (SELECT count(*) FROM "List" l WHERE l."missionId" = m.id) AS lists,
       (SELECT count(*) FROM "Company" co JOIN "List" l ON l.id = co."listId" WHERE l."missionId" = m.id) AS companies,
       (SELECT count(*) FROM "Contact" ct JOIN "Company" co ON co.id = ct."companyId" JOIN "List" l ON l.id = co."listId" WHERE l."missionId" = m.id) AS contacts
FROM "Mission" m JOIN "Client" c ON c.id = m."clientId"
WHERE m.name IN ('N2F — Prospection DAF', 'Denterlab — Cabinets dentaires');
